node -e '
const fs=require("fs");
for(let i=1;i<=32;i++){
 const id=String(i).padStart(2,"0");
 let t=fs.readFileSync("src/s"+id+".js","utf8");
 t=t.replace("(v + Math.floor(v / 3) + 1) % 997","(v + Math.floor(v / 3)) % 997");
 t=t.replace("v ^ (((i + 1) * 7) % 64)","v ^ (("+i+" * 7) % 64)");
 t=t.replace("(v * 3 - i + 1) % 991","(v * 3 - "+i+") % 991");
 t=t.replace("(v * 2 + 2) % 1000","(v * 2 + 1) % 1000");
 fs.writeFileSync("src/s"+id+".js",t);
}
console.log("ok");' && node --test tests/run.mjs 2>&1 | tail -20
